// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    address owner;

    function setUp() public {
        owner = address(this);
        c = new MyContract();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < address(this).balance);
        GasBurner g = new GasBurner();
        vm.deal(address(this), amount + 1 ether);
        vm.deal(address(c), amount);

        vm.prank(owner);
        try c.sendTo(address(g), amount) {
            // sendTo succeeded: c's balance must have dropped by exactly amount.
            // Under P, the receiver burns >2300 gas so `transfer` fails and sendTo reverts.
            assertTrue(false, "sendTo should have reverted with gas-starved transfer");
        } catch {
            assertEq(address(c).balance, amount, "balance must be unchanged on failed transfer");
        }
    }
}

contract GasBurner {
    uint256 x;
    fallback() external payable {
        // consumes far more than the 2300 gas stipend of `transfer`
        for (uint256 i = 0; i < 50; i++) {
            x += i;
        }
    }
}
